package com.bank.vo.model;

import jakarta.persistence.Embeddable;
import java.util.Objects;

@Embeddable   // reusable value object — embedded twice in Customer
public class Address {
    private String street;
    private String city;
    private String pincode;

    protected Address() { }
    public Address(String street, String city, String pincode) {
        this.street = street; this.city = city; this.pincode = pincode;
    }
    @Override public boolean equals(Object o) {
        if (!(o instanceof Address a)) return false;
        return Objects.equals(street, a.street) && Objects.equals(city, a.city)
                && Objects.equals(pincode, a.pincode);
    }
    @Override public int hashCode() { return Objects.hash(street, city, pincode); }
    public String getCity() { return city; }
}
```

