// ─── File: src/main/java/com/bank/vo/model/Customer.java ───
package com.bank.vo.model;

import jakarta.persistence.*;

@Entity
@Table(name = "customers")
public class Customer {
    @Id private String id;
    private String holderName;

    @Embedded                    // Money → balance_amount, balance_currency
    private Money balance;

    @Embedded                    // home address → street, city, pincode (defaults)
    private Address homeAddress;

    @Embedded                    // office address → SAME type, needs renamed columns
    @AttributeOverrides({
        @AttributeOverride(name = "street",  column = @Column(name = "office_street")),
        @AttributeOverride(name = "city",    column = @Column(name = "office_city")),
        @AttributeOverride(name = "pincode", column = @Column(name = "office_pincode"))
    })
    private Address officeAddress;

    protected Customer() { }
    public Customer(String id, String holderName, Money balance,
                    Address home, Address office) {
        this.id = id; this.holderName = holderName; this.balance = balance;
        this.homeAddress = home; this.officeAddress = office;
    }
    public Money getBalance() { return balance; }
    public Address getHomeAddress() { return homeAddress; }
    public Address getOfficeAddress() { return officeAddress; }
}
```

