package com.bank.vo.service;

import com.bank.vo.model.*;
import com.bank.vo.repository.CustomerRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.math.BigDecimal;

@Service
@RequiredArgsConstructor
@Slf4j
public class CustomerService {

    private final CustomerRepository customerRepo;

    @Transactional
    public void onboard() {
        Customer c = new Customer("SAV2001", "Rajesh Kumar",
                new Money(new BigDecimal("1000000.00"), "INR"),
                new Address("MG Road", "Bengaluru", "560001"),
                new Address("Tech Park", "Pune", "411001"));
        customerRepo.save(c);  // one INSERT, all embeddable columns on customers
        log.info("Onboarded {}: home={}, office={}",
                c.getBalance().getAmount(),
                c.getHomeAddress().getCity(), c.getOfficeAddress().getCity());
    }
}
